",\"updatable\"]},{\"name\":\"ip\",\"data_type\":\"inet\",\"format\":\"inet\",\"options\":[\"nullable\",\"updatable\"]},{\"name\":\"tag\",\"data_type\":\"text\",\"format\":\"text\",\"options\":[\"nullable\",\"updatable\"]},{\"name\":\"refresh_token_hmac_key\",\"data_type\":\"text\",\"format\":\"text\",\"options\":[\"nullable\",\"updatable\"]},{\"name\":\"refresh_token_counter\",\"data_type\":\"bigint\",\"format\":\"int8\",\"options\":[\"nullable\",\"updatable\"]},{\"name\":\"scopes\",\"data_type\":\"text\",\"format\":\"text\",\"options\":[\"nullable\",\"updatable\"],\"check\":\"scopes IS NULL OR length(scopes) <= 4096\"},{\"name\":\"aal\",\"data_type\":\"text\",\"format\":\"text\",\"options\":[\"nullable\",\"updatable\"],\"check\":\"aal = ANY (ARRAY['aal1'::text, 'aal2'::text, 'aal3'::text])\"},{\"name\":\"factor_id\",\"data_type\":\"uuid\",\"format\":\"uuid\",\"options\":[\"nullable\",\"updatable\"]},{\"name\":\"created_at\",\"data_type\":\"timestamp with time zone\",\"format\":\"timestamptz\",\"options\":[\"nullable\",\"updatable\"],\"default_value\":\"now()\"},{\"name\":\"updated_at\",\"data_type\":\"timestamp with time zone\",\"format\":\"timestamptz\",\"options\":[\"nullable\",\"updatable\"],\"default_value\":\"now()\"}],\"primary_keys\":[\"id\"],\"foreign_key_constraints\":[{\"name\":\"refresh_tokens_session_id_fkey\",\"source\":\"auth.refresh_tokens.session_id\",\"target\":\"auth.sessions.id\"},{\"name\":\"sessions_user_id_fkey\",\"source\":\"auth.sessions.user_id\",\"target\":\"auth.users.id\"}]},{\"name\":\"auth.refresh_tokens\",\"rls_enabled\":false,\"rows\":0,\"columns\":[{\"name\":\"id\",\"data_type\":\"text\",\"format\":\"text\",\"options\":[\"updatable\"]},{\"name\":\"token\",\"data_type\":\"character varying\",\"format\":\"varchar\",\"options\":[\"updatable\"]},{\"name\":\"user_id\",\"data_type\":\"uuid\",\"format\":\"uuid\",\"options\":[\"updatable\"]},{\"name\":\"session_id\",\"data_type\":\"uuid\",\"format\":\"uuid\",\"options\":[\"nullable\",\"upd