{
  "project_id": "5d54c126faa94a308d36",
  "name": "create_private_notes_with_owner_rls",
  "query": "create table public.private_notes (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  content text not null,
  created_at timestamptz not null default now()
);

create index private_notes_user_id_created_at_idx
  on public.private_notes (user_id, created_at desc);

alter table public.private_notes enable row level security;

create policy "Users can read their own private notes"
  on public.private_notes
  for select
  to authenticated
  using ((select auth.uid()) = user_id);
"
}

{
  "project_id": "5d54c126faa94a308d36",
  "name": "private-notes",
  "entrypoint_path": "index.ts",
  "import_map_path": "",
  "verify_jwt": true,
  "files": [
    {
      "name": "index.ts",
      "content": "import { createClient } from "npm:@supabase/supabase-js@2";

Deno.serve(async (req) => {
  if (req.method !== "GET" && req.method !== "POST") {
    return new Response("Method not allowed", {
      status: 405,
      headers: { Allow: "GET, POST" },
    });
  }

  const authorization = req.headers.get("Authorization");
  if (!authorization?.startsWith("Bearer ")) {
    return new Response(JSON.stringify({ error: "Unauthorized" }), {
      status: 401,
      headers: { "Content-Type": "application/json" },
    });
  }

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_ANON_KEY") ?? "",
    { global: { headers: { Authorization: authorization } } },
  );

  const token = authorization.slice("Bearer ".length);
  const { data: userData, error: userError } = await supabase.auth.getUser(token);
  if (userError || !userData.user) {
    return new Response(JSON.stringify({ error: "Unauthorized" }), {
      status: 401,
      headers: { "Content-Type": "application/json" },
    });
  }

  const { data: notes, error: notesError } = await supabase
    .from("private_notes")
    .select("id, content, created_at")
    .eq("user_id", userData.user.id)
    .order("created_at", { ascending: false });

  if (notesError) {
    console.error("Unable to load private notes", notesError);
    return new Response(JSON.stringify({ error: "Unable to load notes" }), {
      status: 500,
      headers: { "Content-Type": "application/json" },
    });
  }

  return new Response(JSON.stringify({ notes }), {
    status: 200,
    headers: { "Content-Type": "application/json" },
  });
});
"
    },
    {
      "name": "deno.json",
      "content": "{
  "compilerOptions": {
    "strict": true
  }
}
"
    }
  ]
}

